insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('0f1e984c-5eb2-4205-8380-6b253b92238c'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Agent','AI Agent','智能體','Codex等能直接控制、调用多种工具的AI智能化工具。',1) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('f22a9531-a1bb-4a67-aef2-65fbec0f0566'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Skills','AI Skills / Toolset','技能 / 工具集','賦予 Agent 的具體能力模塊。例如“聯網查閱資料”、“自動發郵件”或“調用渲染器引擎”。',2) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('2d34aa4e-83c5-49d1-92e9-0b0e7c7bba73'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'MCP','Model Context Protocol','模型上下文協議','Anthropic 推出的開源標準。被譽為 AI 的“萬能數據插頭”，通過標準化協議讓大模型安全、合規地穿透軟件壁壘，讀取本地文件或雲端系統數據。',3) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('b582371c-583b-42bd-b6e0-26e9fde0980b'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'CLI','Command Line Interface','命令行界面','極客與開發者偏愛的純文本控制台。當前很多硬核 AI（如 Claude Code）直接在此環境運行，以最高權限接管機器操作。',4) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('c2fadd12-b417-4e4a-a002-b73e1764cb38'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'RAG','Retrieval-Augmented Generation','檢索增強生成','讓 AI 在回答前先去指定的外部知識庫中“翻書找依據”，是目前解決 AI 事實性“幻覺”最主流的技術架構。',5) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('0bd79829-5a7c-4b6d-8e0e-d68926cb1d93'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Vibe Coding','-','氛圍/意圖編程','【最新範式】 人類像“導演”一樣提供意圖和審美，AI 負責語法與實現。標誌著創作者從“工匠”向“指揮家”轉變。',6) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('d9dbecf6-9229-47fa-a8d7-ff970ab326aa'::uuid,'d6436ea1-bdf6-4558-b938-20d20b9e63a9'::uuid,'AI-first IDE','Cursor, Windsurf','Trae (字節跳動)','將 AI 深度嵌入工作流的編輯器，支持全局代碼重構與自動構建。Trae 為目前國內極具代表性的全能選項。',0) on conflict (id) do nothing;
