insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('6cb65e00-95df-4474-a06a-cd85fb657b53'::uuid,'d6436ea1-bdf6-4558-b938-20d20b9e63a9'::uuid,'雲端開發環境','Google AI Studio, Project IDX','阿里雲百煉, 騰訊雲微搭','基於瀏覽器的雲端全棧開發環境或 API 調試平台，免除本地算力與環境配置的煩惱。',2) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('4e66fdaf-de1f-4e26-a670-e169f75854bd'::uuid,'d6436ea1-bdf6-4558-b938-20d20b9e63a9'::uuid,'開源智能體','OpenClaw（龙虾）、MetaGPT','WorkBuddy（騰訊）','打破閉源壁壘的代表。MetaGPT 引入了標準作業程序(SOP)，支持多角色 AI 協同開發。',3) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('ad668fbd-6d7b-4746-b541-7af221b96edf'::uuid,'fd1a19f7-5c41-4dca-9c1f-5113be2eb186'::uuid,'Diffusion Models','Midjourney, Stable Diffusion','可靈 (Kling)','擴散模型。通過噪聲預測與去除實現高保真圖像生成，重塑了視覺藝術的生產管線與審美標准。',0) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('a19772fa-bb46-4417-8678-954d24a111e6'::uuid,'fd1a19f7-5c41-4dca-9c1f-5113be2eb186'::uuid,'Node-based Gen','ComfyUI','Liblib','節點式生成界面。將黑盒化的 AI 繪圖轉化為可視化的邏輯節點，賦予創作者對生成過程的極限控制力。',1) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('3cf8fbce-6a25-42c8-878d-170ba069dcf3'::uuid,'fd1a19f7-5c41-4dca-9c1f-5113be2eb186'::uuid,'Spacetime Patches','Sora (OpenAI)','Vidu','時空補丁技術。將視頻降維為統一的數據切片，實現了從單幀畫面到物理世界動態模擬的跨越。',2) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('786b7347-cea1-4c69-ba43-af1f20389731'::uuid,'e3035b1d-0ac0-4010-90dc-d52f1bc922ea'::uuid,'Remotion','☑️','☑️','“自动化3D特效”嵌入网页用的动画动画、三维动效、字体动效、动态图表等、科学动画等，包含页面视觉特效。',0) on conflict (id) do nothing;
