insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('c6679b22-a777-4127-9d22-b000e2099b55'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Markdown','-','純文本標記語言','一种轻量级的标记语言，可用于在纯文本文档中添加格式化元素，設定Rules。',7) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('216ae8f6-6557-4a67-b78f-ab612862cf77'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'IDE','‌Integrated Development Environment‌','集成开发环境','它把程序设计全过程所需的各项功能集合在一起，为程序设计人员提供完整的服务。',8) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('4e1d96f3-9b0f-4ed8-b091-dbde51bf6cbf'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'workflow','1.	節點（Input/Task）2.	路由（Routing/Path）3.	規則（Rules/Logic）','工作流','把複雜的任務拆解成有規律的輸送帶」，讓事情能順著預設好的軌道自動跑完。',9) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('4b26e1f7-ec18-43b5-a05d-bb1e761f70dc'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Git','-','分散式版本控制系統','遊戲存檔、版本更新內容、歷史紀錄',10) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('a7de793f-223b-4e79-bb51-9cb7088120e6'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Task','-','任務執行列表','要求 AI 模型去執行並完成的特定目標或功能。',11) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('4fe30833-6799-4392-8d9a-a1c868a0c321'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'PRD','Product Requirements Document','產品需求文檔','是將模糊的「AI 願景」轉化為可落地的「工程指令」，確保技術團隊在模型邊界、數據需求與用戶價值之間達成共識的導航地圖。',12) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('8f53f8ce-e5dc-488b-a3ab-b08429383136'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'React','','React 應用','基于React JavaScript，用 React 代码实现html网页的同时，能同步开发 iOS 和 Android 原生应用。目前AI-IDE生產優選。',13) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('4d226b26-7964-4450-902d-8598ccaed5db'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'canvas','','视觉画布','Canvas 是一個能隨時幫你改稿、可視化、以畫布連接邏輯思維的AI畫布。',14) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('9d0fede8-0087-4504-a0a3-e79b4e288ed5'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'FDE','Forward Deployed Engineer','前沿部署工程','Ai驻场交付，全链路闭环，AI技术与落地集成；能力点：1.全栈设计技术2.行业业务洞察3.客户沟通能力。',15) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values ('7480c0af-206b-4166-9828-d42d49942d97'::uuid,'59cbfbed-5e14-4209-899a-db8a8c7b9f84'::uuid,'新術語','-','-','請編輯內容',0) on conflict (id) do nothing;
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values
('3dfd78b2-058f-4cdd-a652-5de60022f50d'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'LLM','Large Language Model','大語言模型','以大規模文本與多模態資料訓練的生成式模型，根據上下文預測後續 Token。擅長語言理解、生成與推理，但輸出仍可能出錯，需配合檢索、工具與評測使用。',0),
('0f1e984c-5eb2-4205-8380-6b253b92238c'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Agent','AI Agent','智能體','以模型為決策核心，能感知上下文、規劃步驟、調用工具並根據結果繼續行動的軟件系統。Agent 不等於模型本身，其可靠性取決於權限、工具、記憶、評測與人工監督。',1),
('f22a9531-a1bb-4a67-aef2-65fbec0f0566'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Skills','Agent Skills / Toolsets','技能 / 工具集','可重用的任務能力包，通常包含操作指引、工具、腳本、範本與領域知識，例如檢索資料、處理文檔或調用渲染器。Skill 規範 Agent 如何完成一類工作，而非單純等同於工具。',2),
('2d34aa4e-83c5-49d1-92e9-0b0e7c7bba73'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'MCP','Model Context Protocol','模型上下文協議','一種開放協議，用標準方式讓 AI 應用連接工具、資料來源與可重用提示。它降低整合成本，但不自動保證安全或合規；權限、驗證、資料邊界與審計仍需由實作方負責。',3),
('b582371c-583b-42bd-b6e0-26e9fde0980b'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'CLI','Command Line Interface','命令行界面','以文字命令與程式互動的介面，便於自動化、批次處理與組合工具。CLI 型 Agent 只擁有使用者或沙箱授予的權限，不應預設為最高權限。',4),
('c2fadd12-b417-4e4a-a002-b73e1764cb38'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'RAG','Retrieval-Augmented Generation','檢索增強生成','在生成前檢索外部資料，並把相關片段加入模型上下文，以提升時效性、可追溯性與領域覆蓋。RAG 能降低部分事實錯誤，但效果仍取決於資料品質、檢索、排序與引用驗證。',5),
('0bd79829-5a7c-4b6d-8e0e-d68926cb1d93'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Vibe Coding','Vibe Coding','氛圍編程 / 意圖驅動編程','以自然語言描述意圖並快速接受、試用 AI 生成代碼的開發方式，重視迭代速度與結果體驗。適合原型探索；進入生產環境仍需理解代碼、測試、安全審查與版本控制。',6),
('c6679b22-a777-4127-9d22-b000e2099b55'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Markdown','Markdown','純文本標記語言','用簡潔符號為純文字添加標題、列表、連結與程式碼等結構的輕量標記語言，常用於 README、文檔、提示與 Agent 指令文件。不同解析器支持的擴展語法可能不同。',7),
('216ae8f6-6557-4a67-b78f-ab612862cf77'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'IDE','Integrated Development Environment','整合開發環境','把程式編輯、執行、除錯、測試、版本控制與專案管理整合在同一工作環境中的軟件。AI-first IDE 會在此基礎上加入程式理解、生成與 Agent 工作流。',8),
('4e1d96f3-9b0f-4ed8-b091-dbde51bf6cbf'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Workflow','Workflow','工作流','將任務拆成可追蹤的步驟、依賴、路由與規則，使人、模型和工具按條件協作。工作流可以是固定流程，也可以包含由 Agent 動態決策的分支。',9),
('4b26e1f7-ec18-43b5-a05d-bb1e761f70dc'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Git','Git','分散式版本控制系統','分散式版本控制系統，用提交記錄追蹤文件變更，並以分支、合併與回退支持多人協作。可類比為帶完整差異與歷史的專案存檔系統。',10),
('a7de793f-223b-4e79-bb51-9cb7088120e6'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Task','Task','任務','具有明確目標、輸入、約束與完成標準的工作單元，可由人、模型或 Agent 執行。任務列表只是管理多個 Task 的一種介面。',11),
('4fe30833-6799-4392-8d9a-a1c868a0c321'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'PRD','Product Requirements Document','產品需求文檔','描述產品目標、使用者、需求範圍、流程、約束與驗收標準的文件。AI 產品的 PRD 還應明確模型邊界、資料需求、評測指標、安全風險與人工兜底。',12),
('8f53f8ce-e5dc-488b-a3ab-b08429383136'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'React','React','React 前端函式庫','用元件與狀態模型構建 Web 使用者介面的 JavaScript 函式庫。React 本身不會直接生成 iOS 或 Android 原生應用；跨平台原生開發通常使用相關但獨立的 React Native。',13),
('4d226b26-7964-4450-902d-8598ccaed5db'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Canvas','Canvas / Visual Workspace','視覺畫布 / 可視化工作區','以自由佈局方式組織文字、圖像、節點與連線的工作介面，適合構思、改稿和呈現關係。它是互動形態，不等同於 HTML Canvas API，也不必然包含 AI。',14),
('9d0fede8-0087-4504-a0a3-e79b4e288ed5'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'FDE','Forward Deployed Engineer','前線部署工程師 / 駐場交付工程師','深入客戶現場，把通用技術產品配置、整合並迭代為可用業務方案的工程角色。核心能力涵蓋軟件工程、領域洞察、需求拆解、客戶溝通與交付閉環，並不限於 AI。',15),
('11111111-1111-4111-8111-111111111111'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Transformer','Transformer Architecture','Transformer 架構','以注意力機制為核心的神經網絡架構，可並行處理序列並學習長距離關係，是多數現代大語言模型與多模態模型的基礎。',16),
('22222222-2222-4222-8222-222222222222'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Token','Token','詞元 / 標記','模型讀取與生成內容的基本計算單位，可能是一個字、詞的一部分、符號或其他資料片段。Token 數量會影響上下文容量、延遲與使用成本。',17),
('33333333-3333-4333-8333-333333333333'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Context Window','Context Window','上下文窗口','模型在一次請求中可共同參考的輸入與輸出 Token 範圍。窗口更大不代表模型能同等準確地使用其中所有信息，仍需良好的結構、檢索與摘要策略。',18),
('44444444-4444-4444-8444-444444444444'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Prompt','Prompt / Instruction','提示 / 指令','提供給模型的任務說明、上下文、約束與輸出要求。高品質提示通常明確目標、資料邊界和驗收標準，但不能取代工具權限、程式驗證與系統設計。',19),
('55555555-5555-4555-8555-555555555555'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Embedding','Embedding / Vector Representation','嵌入向量 / 向量表徵','把文字、圖像或其他資料映射為數值向量，使語義相近的內容在向量空間中更接近。常用於語義搜尋、聚類、推薦與 RAG 檢索。',20),
('66666666-6666-4666-8666-666666666666'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Tool Calling','Tool Calling / Function Calling','工具調用 / 函數調用','模型按預定義結構選擇工具並產生參數，由應用實際執行，再把結果返回模型。它讓模型能查資料或採取行動，但必須配合參數驗證、權限控制與確認機制。',21),
('77777777-7777-4777-8777-777777777777'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Inference','Model Inference','模型推理 / 推論','使用已訓練模型對新輸入產生預測或內容的運行階段。推理品質、速度與成本會受模型、硬件、上下文長度、取樣參數及快取策略影響。',22),
('88888888-8888-4888-8888-888888888888'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Fine-tuning','Fine-tuning / Post-training','微調 / 後訓練','在基礎模型之上使用特定資料或偏好訊號繼續訓練，以調整行為、風格或任務能力。它適合穩定改變模型行為；需要即時外部知識時通常優先考慮 RAG。',23),
('99999999-9999-4999-8999-999999999999'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Hallucination','Model Hallucination','模型幻覺','模型生成看似合理但缺乏依據、與來源矛盾或事實錯誤的內容。可透過檢索、引用、工具查證、結構化輸出、評測與人工覆核降低風險，但難以完全消除。',24),
('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Multimodality','Multimodality','多模態','模型理解或生成文字、圖像、音訊、影片等多種資料形態的能力。多模態系統需要處理不同模態的對齊、時序、解析度、版權與隱私問題。',25),
('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Evals','Evaluations / Evals','模型與系統評測','用可重複的資料集、指標與人工標準衡量模型或 Agent 的品質、可靠性、安全性、延遲與成本。評測應覆蓋真實任務、邊界案例及版本回歸。',26),
('cccccccc-cccc-4ccc-8ccc-cccccccccccc'::uuid,'087cde3a-f15f-4186-ac5d-23c5d9ae8ba5'::uuid,'Guardrails','AI Guardrails','安全護欄 / 行為約束','在模型前後與工具執行層設置的政策、權限、輸入輸出檢查、人工確認和監控機制，用於降低越權、資料洩漏、不安全內容與錯誤操作風險。',27)
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values
('d9dbecf6-9229-47fa-a8d7-ff970ab326aa'::uuid,'d6436ea1-bdf6-4558-b938-20d20b9e63a9'::uuid,'AI-native IDE','Cursor, Windsurf','Trae、Qoder、通義靈碼','把程式碼理解、對話、補全、跨文件修改、終端與 Agent 工作流整合進開發環境。其價值不只在生成代碼，更在於利用專案上下文完成可審查、可回退的多步變更。',0),
('08e55c56-2809-4254-b0af-e953503db363'::uuid,'d6436ea1-bdf6-4558-b938-20d20b9e63a9'::uuid,'CLI Coding Agent','Claude Code, Codex CLI, Gemini CLI','命令行編程智能體','在終端中讀取代碼庫、編輯文件、執行命令與測試的編程 Agent。它適合自動化和遠端環境，但能力受工作目錄、沙箱、網絡與授權策略約束，不應被視為無限制接管電腦。',1),
('6cb65e00-95df-4474-a06a-cd85fb657b53'::uuid,'d6436ea1-bdf6-4558-b938-20d20b9e63a9'::uuid,'Cloud Development Environment','GitHub Codespaces, Firebase Studio, Replit','雲端開發環境','在瀏覽器或遠端容器中提供代碼、終端、預覽與部署能力的開發環境。它降低本地配置成本並提升環境一致性，但需關注休眠、資源配額、網絡延遲、資料駐留與供應商鎖定。',2),
('4e66fdaf-de1f-4e26-a670-e169f75854bd'::uuid,'d6436ea1-bdf6-4558-b938-20d20b9e63a9'::uuid,'Open-source Coding Agent','OpenHands, Aider, Cline','開源編程智能體','源碼公開、可自託管或二次開發的編程 Agent。其優勢是可審計與可定制，但模型費用、沙箱隔離、憑證管理、依賴安全與維護仍由部署者承擔。',3),
('d2000001-0000-4000-8000-000000000001'::uuid,'d6436ea1-bdf6-4558-b938-20d20b9e63a9'::uuid,'Code Completion','Inline Code Completion','代碼補全','根據游標位置、鄰近代碼與專案上下文預測下一段代碼的輔助方式。它適合局部、低延遲編寫；跨文件規劃、執行與驗證則通常需要 Agent 模式。',4),
('d2000002-0000-4000-8000-000000000002'::uuid,'d6436ea1-bdf6-4558-b938-20d20b9e63a9'::uuid,'Repository Context','Codebase Indexing / Repository Context','代碼庫上下文 / 索引','透過搜尋、符號索引、語義檢索與依賴分析，向模型提供與任務相關的文件和結構。上下文品質往往比一次塞入整個代碼庫更重要。',5),
('d2000003-0000-4000-8000-000000000003'::uuid,'d6436ea1-bdf6-4558-b938-20d20b9e63a9'::uuid,'Agent Mode','Agentic Coding Workflow','智能體開發模式','讓 AI 圍繞目標循環進行理解、規劃、修改、執行、觀察與修正的工作模式。與一次性問答相比，它能完成更長任務，也更需要檢查點、停止條件與人工覆核。',6),
('d2000004-0000-4000-8000-000000000004'::uuid,'d6436ea1-bdf6-4558-b938-20d20b9e63a9'::uuid,'Sandbox & Permissions','Execution Sandbox / Permission Model','執行沙箱與權限模型','限制 Agent 可讀寫文件、運行命令、訪問網絡與調用外部服務的安全邊界。最小權限、操作前確認和可追溯審計是生產使用的核心保障。',7),
('d2000005-0000-4000-8000-000000000005'::uuid,'d6436ea1-bdf6-4558-b938-20d20b9e63a9'::uuid,'Human-in-the-loop','Human-in-the-loop Development','人在迴路 / 人工覆核','在需求澄清、方案選擇、高風險操作與合併發布等節點保留人工判斷。目標不是逐步干預，而是在最關鍵的位置建立可驗證的控制點。',8),
('d2000006-0000-4000-8000-000000000006'::uuid,'d6436ea1-bdf6-4558-b938-20d20b9e63a9'::uuid,'CI/CD','Continuous Integration / Continuous Delivery','持續整合 / 持續交付','透過自動化構建、測試、掃描和部署，使代碼變更能持續驗證與交付。Agent 生成代碼後仍應進入同一品質門禁，而不是繞過工程流程。',9),
('d2000007-0000-4000-8000-000000000007'::uuid,'d6436ea1-bdf6-4558-b938-20d20b9e63a9'::uuid,'Code Review','AI-assisted Code Review','代碼審查','檢查變更的正確性、可維護性、安全性與影響範圍。AI 可輔助定位風險和生成測試，但最終判斷應基於差異、運行證據與專案標準。',10),
('d2000008-0000-4000-8000-000000000008'::uuid,'d6436ea1-bdf6-4558-b938-20d20b9e63a9'::uuid,'Agent Observability','Agent Tracing / Observability','智能體可觀測性','記錄提示、工具調用、文件修改、測試結果、耗時與錯誤，以便重現和評估 Agent 行為。生產指標應同時關注任務成功率、回歸、成本與人工接管率。',11)
insert into public.entries (id,category_id,term,intl,cn,description,sort_order) values
('ad668fbd-6d7b-4746-b541-7af221b96edf'::uuid,'fd1a19f7-5c41-4dca-9c1f-5113be2eb186'::uuid,'Diffusion Models','Diffusion-based Generative Models','擴散生成模型','學習逐步逆轉加噪過程，從隨機噪聲生成圖像或影片的模型家族。擴散描述的是生成方法，不能把 Midjourney、Stable Diffusion、可靈等不同產品直接視為同一底層架構。',0),
('a19772fa-bb46-4417-8678-954d24a111e6'::uuid,'fd1a19f7-5c41-4dca-9c1f-5113be2eb186'::uuid,'Node-based Workflow','ComfyUI','LiblibAI 工作流','以節點和連線組合模型載入、條件控制、採樣、後處理與輸出的可視化工作流。它提升可重用性與可調試性，但不改變底層模型本身的能力與限制。',1),
('3cf8fbce-6a25-42c8-878d-170ba069dcf3'::uuid,'fd1a19f7-5c41-4dca-9c1f-5113be2eb186'::uuid,'Video Generation','Sora, Veo, Runway','可靈、Vidu、即夢','由文字、圖像或影片條件生成新影片的模型與產品類別。常見系統把壓縮後的時空片段作為序列建模，但產品實作並不完全相同；核心難點包括時序一致性、運動合理性與可控性。',2),
('d3000001-0000-4000-8000-000000000001'::uuid,'fd1a19f7-5c41-4dca-9c1f-5113be2eb186'::uuid,'Latent Diffusion','Latent Diffusion Model (LDM)','潛空間擴散模型','先用編碼器把圖像壓縮到潛空間，再在較低維表示上執行擴散生成，最後解碼為圖像。這能顯著降低高解析度生成的計算成本，但壓縮也可能損失細節。',3),
('d3000002-0000-4000-8000-000000000002'::uuid,'fd1a19f7-5c41-4dca-9c1f-5113be2eb186'::uuid,'DiT','Diffusion Transformer','擴散 Transformer','以 Transformer 取代傳統 U-Net 作為擴散模型骨幹，對潛空間圖像或影片片段進行建模。其優勢是易於擴展算力與模型規模，已成為多類生成系統的重要架構。',4),
('d3000003-0000-4000-8000-000000000003'::uuid,'fd1a19f7-5c41-4dca-9c1f-5113be2eb186'::uuid,'Flow Matching','Flow Matching / Rectified Flow','流匹配 / 校正流','學習把噪聲分佈沿連續路徑運輸到資料分佈的向量場方法，可用較少步數進行生成。它與擴散相關但並非同義，實際品質和速度取決於訓練與採樣設計。',5),
('d3000004-0000-4000-8000-000000000004'::uuid,'fd1a19f7-5c41-4dca-9c1f-5113be2eb186'::uuid,'Text-to-Image','Text-to-Image Generation','文生圖','根據文字提示生成圖像的任務。效果受提示理解、訓練資料、構圖能力與解碼品質影響；涉及品牌、人物或商用素材時還需考慮版權、肖像權與來源標註。',6),
('d3000005-0000-4000-8000-000000000005'::uuid,'fd1a19f7-5c41-4dca-9c1f-5113be2eb186'::uuid,'Image-to-Image','Image-conditioned Generation / Editing','圖生圖 / 圖像編輯','以參考圖像配合文字或其他條件生成新圖，用於風格轉換、局部修改、姿態保持和版本探索。輸出與原圖的一致程度取決於條件強度和模型編輯能力。',7),
('d3000006-0000-4000-8000-000000000006'::uuid,'fd1a19f7-5c41-4dca-9c1f-5113be2eb186'::uuid,'Inpainting & Outpainting','Inpainting / Outpainting','局部重繪 / 畫面擴展','Inpainting 在遮罩區域內重建或替換內容；Outpainting 則向畫布外延伸場景。高品質結果需要兼顧邊界融合、光影、透視與主體一致性。',8),
('d3000007-0000-4000-8000-000000000007'::uuid,'fd1a19f7-5c41-4dca-9c1f-5113be2eb186'::uuid,'ControlNet','ControlNet / Spatial Conditioning','空間條件控制','在預訓練文生圖模型上加入邊緣、深度、姿態、分割等空間條件，使構圖更可控。它提升約束能力，但不保證身份、材質或細節完全一致。',9),
('d3000008-0000-4000-8000-000000000008'::uuid,'fd1a19f7-5c41-4dca-9c1f-5113be2eb186'::uuid,'LoRA','Low-Rank Adaptation','低秩適配','以少量可訓練參數適配大型模型的高效微調方法，常用於角色、風格或領域定制。LoRA 文件較小且易組合，但可能過擬合、產生概念串擾或放大資料偏差。',10),
('d3000009-0000-4000-8000-000000000009'::uuid,'fd1a19f7-5c41-4dca-9c1f-5113be2eb186'::uuid,'Temporal Consistency','Temporal Consistency / Motion Coherence','時序一致性 / 運動連貫性','影片生成中角色身份、物體外觀、場景結構和運動在連續幀間保持穩定的程度。它是區分單幀品質與完整影片可用性的核心指標。',11),
('d3000010-0000-4000-8000-000000000010'::uuid,'fd1a19f7-5c41-4dca-9c1f-5113be2eb186'::uuid,'Upscaling','Super-resolution / Upscaling','超解析度 / 放大','從低解析度輸入生成更高解析度結果的後處理任務。生成式放大器可補充紋理，但新增細節不一定真實，證據型圖像或科研資料應避免把推測細節當作原始信息。',12),
('d3000011-0000-4000-8000-000000000011'::uuid,'fd1a19f7-5c41-4dca-9c1f-5113be2eb186'::uuid,'3D Generation','Text-to-3D / Image-to-3D','文生 3D / 圖生 3D','由文字或圖像生成網格、點雲、神經表示、材質或多視圖資產。評估不只看單一渲染圖，還需檢查幾何拓撲、多視角一致性、材質與下游軟件兼容性。',13)
